import { db } from "./FirebaseConfig";
import { doc, setDoc, getDoc, updateDoc, arrayUnion } from "firebase/firestore";
import {
  specialSpotifyPlaylist,
  specialSpotifyPlaylistType,
  Week,
} from "./models"; // 🔹 Import class, not interface
import { collection, getDocs, deleteDoc } from "firebase/firestore";

/**
 * Pushes the entire data structure into a single Firestore document.
 * @param {Quarter[]} quarters - An array of Quarter class instances
 */
export const pushDataToFirestore = async (weeks: Week[]): Promise<void> => {
  try {
    const docRef = doc(
      db,
      "picksData",
      "picksDataDocument",
      "QuartersCollection",
      "SQ24"
    );
    await setDoc(docRef, {
      weeks: weeks.map((w) => w.toFirestore(), { merge: true }),
    });

    console.log("✅ Data successfully added to Firestore!");
  } catch (error) {
    console.error("❌ Error adding data to Firestore:", error);
  }
};

/**
 * Deletes all documents from the `picksData` collection in Firestore.
 */
export const resetFirestoreDatabase = async () => {
  try {
    const querySnapshot = await getDocs(collection(db, "picksData"));

    querySnapshot.forEach(async (document) => {
      await deleteDoc(doc(db, "picksData", document.id));
    });

    console.log("✅ Firestore database has been reset.");
  } catch (error) {
    console.error("❌ Error resetting Firestore database:", error);
  }
};

