export const addToExistingDocument = async (
  newWeeks: Week[]
): Promise<void> => {
  try {
    const docRef = doc(
      db,
      "picksData",
      "picksDataDocument",
      "QuartersCollection",
      "SQ24"
    );

    // Get the existing document
    const docSnap = await getDoc(docRef);

    if (docSnap.exists()) {
      // If the document exists, merge new data into the existing quarters array
      const existingData = docSnap.data();
      const existingWeeks = existingData.quarters || [];

      // Merge new data with existing data
      const updatedWeeks = [
        ...existingWeeks,
        ...newWeeks.map((q) => q.toFirestore()),
      ];

      // Update Firestore with merged data
      await setDoc(docRef, { weeks: updatedWeeks }, { merge: true });

      console.log("✅ Data successfully merged into the existing document!");
    } else {
      // If the document doesn't exist, create it with new data
      await setDoc(docRef, {
        weeks: newWeeks.map((w) => w.toFirestore()),
      });

      console.log("✅ New document created with initial data!");
    }
  } catch (error) {
    console.error("❌ Error adding data to Firestore:", error);
  }
};

