export const replaceSocialLink = async (
  docId: string,
  newLinks: { toFirestore: () => any }[]
): Promise<void> => {
  try {
    const docRef = doc(db, "socialsLinks", docId);
    const docSnap = await getDoc(docRef);

    const updatedLinks = newLinks.map((link) => link.toFirestore());

    await setDoc(docRef, { link: updatedLinks });

    console.log("✅ Link field successfully overwritten in the document!");
  } catch (error) {
    console.error("❌ Error updating social link:", error);
  }
};

export const deleteWheelEntry = async (
  category: "Albums" | "Songs" | "OnceThrough",
  item: string
) => {
  try {
    const ref = doc(db, "nameWheel", category);
    const snap = await getDoc(ref);
    if (!snap.exists()) {
      console.error(`Document for ${category} does not exist`);
      return;
    }
    const data = snap.data();
    if (!data.names || !Array.isArray(data.names)) {
      console.error(`No 'items' array found in ${category}`);
      return;
    }
    const filtered = data.names.filter((entry: string) => entry !== item);
    await updateDoc(ref, { names: filtered });
    console.log(`Deleted "${item}" from ${category}`);
  } catch (error) {
    console.error("Error deleting wheel entry:", error);
  }
};

export const addWheelEntry = async (docId: string, name: string) => {
  const ref = doc(db, "nameWheel", docId);
  await updateDoc(ref, {
    names: arrayUnion(name),
  });
};

export const updateNextWeeksPick = async (field: string, value: string) => {
  const ref = doc(db, "picksToAdd", "nextWeeksPicks");
  await updateDoc(ref, {
    [`nextWeek.${field}`]: value,
  });
};
